package com.graduation.rental.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(RentalListingRepository listings, com.graduation.rental.auth.SeedAuthBridge auth){return args->{if(listings.count()==0){var x=new RentalListing();x.setTitle("大学城地铁口一居室");x.setCity("宜昌");x.setDistrict("西陵区");x.setAddress("大学路 18 号");x.setMonthlyRent(new java.math.BigDecimal("1450"));x.setBedrooms(1);x.setAreaSqm(new java.math.BigDecimal("38.5"));x.setDescription("独立卫浴，近公交站，采光良好");x.setContact("13800000000");x.setOwnerUserId(auth.currentUserSeedId());x.setStatus("PUBLISHED");listings.save(x);}};}}
